  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "[18F]SP203, which shares the 3-fluoro-5-(alkynyl)benzonitrile core of the query, showed high BBB permeability in human PET studies (%SUV ~580), directly supporting meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "[11C]MPEPy, a close mGluR5 ligand containing the pyridyl-alkyne motif, readily crosses the BBB in PET studies, although P-gp-mediated efflux lowers its free brain concentration; this supports CNS entry while flagging a possible efflux component.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The mGluR1 PET ligand [18F]FPTQ showed rapid brain influx in mice (2.5% ID/g within minutes), demonstrating that small, lipophilic heteroaromatic PET ligands of this class achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In rats, 18F-FPP rapidly entered the CNS after intravenous administration, providing additional in vivo evidence that small lipophilic radiotracers with similar physicochemical properties penetrate the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, lipophilic, neutral mGluR5 PET ligand with highly favorable passive BBB properties; direct human PET evidence from the closely related SP203 and ready brain entry of MPEPy, FPTQ, and FPP support meaningful CNS access. No contradictory experimental evidence was identified.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule is present in the supplied evidence.",
    "P-gp efflux status of the query was not directly measured, though the close analogue MPEPy shows some efflux liability.",
    "Metabolic instability of the alkyne could affect sustained in vivo exposure but not initial BBB penetration."
  ],
